'use strict';

var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('fails on the patched build', function () {
    // multi-digit values with a unit must be parsed with the unit applied
    assert.strictEqual(bytes('100kb'), 102400);
    assert.strictEqual(bytes('10kb'), 10240);
    assert.strictEqual(bytes.parse('1024mb'), 1073741824);
    assert.strictEqual(bytes.parse('-100kb'), -102400);
  });
});

var assert = require('assert');
var bytes = require('..');

describe('proof', function () {
  it('keeps the default of two decimal places when options omit decimalPlaces', function () {
    assert.strictEqual(bytes(1500, {}), '1.46KB');
    assert.strictEqual(bytes(1500, { unitSeparator: ' ' }), '1.46 KB');
    assert.strictEqual(bytes(1500, { fixedDecimals: true }), '1.46KB');
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load, dump } from 'js-yaml';

describe('proof', () => {
  it('fails on the patched build', () => {
    // Signed binary integers must still resolve under an explicit !!int tag
    // in the default (core) schema.
    assert.strictEqual(load('!!int "-0b1010"'), -10);
    assert.strictEqual(load('!!int "+0b1010"'), 10);
    // Unsigned binary must keep working as well.
    assert.strictEqual(load('!!int "0b1010"'), 10);
  });
});

import { describe, it } from 'node:test';
import assert from 'node:assert';
import { load } from 'js-yaml';

describe('proof', () => {
  it('resolves explicitly tagged unsigned octal integers', () => {
    assert.strictEqual(load('0o17'), 15); // implicit form still works
    assert.strictEqual(load('!!int 0o17'), 15); // explicit form must behave the same
    assert.strictEqual(load('!!int -0o17'), -15);
    assert.strictEqual(load('!!int +0o17'), 15);
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('throws the documented Error (not a TypeError) for null and undefined', function () {
    assert.throws(function () {
      ms(null);
    }, /val is not a non-empty string or a valid number\. val=null/);

    assert.throws(function () {
      ms(undefined);
    }, /val is not a non-empty string or a valid number\. val=undefined/);
  });

  it('refuses non-string values that happen to have a length property', function () {
    assert.throws(function () {
      ms(['2 days']);
    }, /val is not a non-empty string or a valid number/);
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('pluralizes at exactly 1.5 units like upstream ms', function () {
    // msAbs === n * 1.5 exactly, and Math.round(1.5) === 2,
    // so upstream ms (which uses >=) pluralizes these.
    assert.strictEqual(ms(1500, { long: true }), '2 seconds');
    assert.strictEqual(ms(90000, { long: true }), '2 minutes');
    assert.strictEqual(ms(5400000, { long: true }), '2 hours');
    assert.strictEqual(ms(129600000, { long: true }), '2 days');
  });
});

var assert = require('assert');
var ms = require('./');

describe('proof', function () {
  it('keeps the descriptive message when throwing on invalid input', function () {
    assert.throws(function () {
      ms('');
    }, function (err) {
      return err instanceof Error &&
        err.message === 'val is not a non-empty string or a valid number. val=' + JSON.stringify('');
    });

    assert.throws(function () {
      ms(NaN);
    }, function (err) {
      return err instanceof Error &&
        err.message === 'val is not a non-empty string or a valid number. val=' + JSON.stringify(NaN);
    });
  });
});

